import app.quietagent.workspace.*;import org.json.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
public final class ToolExecutorHostTests{static void ok(boolean b,String m){if(!b)throw new AssertionError(m);}public static void main(String[]x)throws Exception{Path outer=Paths.get("build","host-tools");Files.createDirectories(outer);Path p=Files.createTempDirectory(outer,"run-");try{WorkspaceStore s=new WorkspaceStore(p.resolve("results").toFile());ToolExecutor e=new ToolExecutor(s,null);JSONObject a=new JSONObject().put("rootId","private").put("name","a.txt").put("body","hello");JSONObject r=e.execute("report",a);String id=r.getString("id");ok(e.metadata().getJSONArray("tools").toString().contains("receipt_batch"),"receipt batch advertised");ok(e.execute("stat",new JSONObject().put("id",id)).getBoolean("directory")==false,"stat");ok(e.execute("read_document",new JSONObject().put("id",id)).getString("text").contains("hello"),"read");JSONArray batchIds=new JSONArray();for(int i=0;i<20;i++)batchIds.put(s.create("private","sms-"+i+".txt","message "+i));JSONObject batch=e.execute("read_documents",new JSONObject().put("ids",batchIds).put("limitPerItem",200));ok(batch.getInt("count")==20&&batch.getJSONArray("items").getJSONObject(19).getString("text").contains("19"),"batch read 20");try{e.execute("read_documents",new JSONObject().put("ids",new JSONArray(batchIds.toString()).put(id)));throw new AssertionError("batch >20 accepted");}catch(Exception expected){}JSONArray eleven=new JSONArray();for(int i=0;i<11;i++)eleven.put(id);try{e.execute("receipt_batch",new JSONObject().put("ids",eleven));throw new AssertionError("receipt batch >10 accepted");}catch(Exception expected){}e.execute("mkdir",new JSONObject().put("parent","private:").put("name","d"));e.execute("write_table",new JSONObject().put("rootId","private").put("name","d/table.csv").put("headers",new JSONArray().put("a")).put("rows",new JSONArray().put(new JSONArray().put("b"))));e.execute("zip",new JSONObject().put("rootId","private").put("name","d/out.zip").put("ids",new JSONArray().put(id)));e.execute("copy",new JSONObject().put("id",id).put("destination","private:d"));e.execute("move",new JSONObject().put("id","private:d/a.txt").put("destination","private:"));e.execute("trash",new JSONObject().put("id",id));try{e.execute("stat",new JSONObject().put("id",id).put("bad",1));throw new AssertionError("unknown args");}catch(Exception expected){}try{e.execute("bogus",new JSONObject());throw new AssertionError("unknown tool");}catch(Exception expected){}System.out.println("ToolExecutorHostTests OK");}finally{try(java.util.stream.Stream<Path>z=Files.walk(p)){z.sorted(java.util.Comparator.reverseOrder()).forEach(q->{try{Files.deleteIfExists(q);}catch(Exception ignored){}});}}}}
